@app.post("/validate")
async def validate(request: Request):
    header = request.header
    for h in header_list:
        if h not in header:
            return {"code": 400, "msg": "header not found"}
    nt = int(time.time())
    random.seed(nt)
    pc = p.copy()
    ks = list(pc.keys())
    random.shuffle(ks)
    hs = ""
    for f in ks:
        random.seed(f)
        base_address = random.randint(0x1000, 0x16000)
        hs += request.header[
            "X-NWWN-"
            + (pc[f][base_address : base_address + 10]).strip(b"\x00").decode()
        ]
    try:
        dec = DES.new(str(nt).ljust(16, "\x06").encode(), DES.MODE_ECB).decrypt(
            base64.b64decode(hs.encode()).ljust(16, b"\x06")
        )
    except Exception:
        return {"code": 400, "msg": "decrypt failed"}

    decc = dec.decode().removeprefix(request.path).strip("\t")
    for i in range(10):
        decc = decc.strip(chr(i))
    if (
       decc .strip()
     != base64.b64decode(request.body).decode().strip())    :
        return {"code": 400, "msg": "path not match"}
    return {"code": 200, "msg": flag}


